import{_ as o,l,o as e,c as s,v as t,p as n,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"WAF","description":"","frontmatter":{"title":"WAF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/waf.md","filePath":"cs/waf.md","lastUpdated":1789023840000}'),c={name:"cs/waf.md"};function A(_,a,f,u,E,m){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="waf" tabindex="-1">WAF <a class="header-anchor" href="#waf" aria-label="Permalink to &quot;WAF&quot;">​</a></h1><div class="epigraph"><p>Web 应用防火墙在应用前按规则看 HTTP。它能挡已知噪声与部分注入形态，但不是规格：编码绕过与业务逻辑它几乎看不见。把它当补偿控制，不要当根治。</p><footer>—— 据 OWASP 对 WAF；ModSecurity 核心规则集作为工程实例点名</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/credential-stuffing">撞库</a>提到自动化。缺口是<strong>边缘过滤</strong>。本课讲 WAF 能做什么不能做什么，不写绕过 WAF 的配方。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>正则挡经典 SQL 与 XSS 形态。双重编码、JSON 换位置会漏。误杀伤害可用。缺口是：正位是应用修复，WAF 缩窗口。</p><h3 id="虚拟补丁" tabindex="-1">虚拟补丁 <a class="header-anchor" href="#虚拟补丁" aria-label="Permalink to &quot;虚拟补丁&quot;">​</a></h3><p>N-day 窗口里可挡已知路径，仍要打补丁。</p><p><span class="marginnote">CRS。禁止绕过教程。API 安全下一课：现代攻击面常在 JSON API 而非页面。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>部署：正向允许、日志、调参。对照下一课 BOLA：WAF 几乎不管客体授权。</p>',12)),(e(),n(p,null,{default:r(()=>[h(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20HTTP%5B%22%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20RULE%5B%22%E7%AD%BE%E5%90%8D%E6%88%96%E6%AD%A3%E5%88%99%22%5D%0A%20%20RULE%20--%3E%20PASS%5B%22%E5%88%B0%E5%BA%94%E7%94%A8%22%5D%0A%20%20RULE%20--%3E%20LIM%5B%22%E6%BC%8F%E8%BF%87%E7%BC%96%E7%A0%81%E4%B8%8E%E9%80%BB%E8%BE%91%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>纵深的边缘层。真正的授权在应用。BOLA 下一课。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写绕过。API 安全与 BOLA 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>限流之后，WAF 挡已知 HTTP 噪声。</li><li>补偿控制，不是编码替代。</li><li>看不见客体级授权。</li><li>下一课 BOLA。</li><li>出处：OWASP WAF；ModSecurity CRS。</li></ul>',8))])}const S=o(c,[["render",A]]);export{P as __pageData,S as default};
